const { createRequire } = require('module');
const req = createRequire('C:/Users/user/AppData/Local/Temp/skill-eval-ZOqxdJ/package.json');
const lk = req('lodash/kebabCase'), lkb = req('lodash/keyBy'), lt = req('lodash/truncate');
const et = req('es-toolkit'), ec = req('es-toolkit/compat');
const ek = et.kebabCase, ekb = et.keyBy, etr = ec.truncate;
const rnd = n => Math.floor(Math.random()*n);
const pick = s => s[rnd(s.length)];
let fails = {kebab:0, keyBy:0, trunc:0}, samples = {};
const SLUG = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 -_.';
for (let i=0;i<200000;i++){
  let len = rnd(41), s=''; for(let j=0;j<len;j++) s+=pick(SLUG);
  if (lk(s)!==ek(s)) { fails.kebab++; samples.kebab=samples.kebab||[s,lk(s),ek(s)]; }
}
const NAMES=['kim','park','lee','choi','jung'];
for (let i=0;i<50000;i++){
  let n=rnd(13), rows=[]; for(let j=0;j<n;j++) rows.push({id:rnd(10),name:pick(NAMES),age:18+rnd(43)});
  const a=JSON.stringify(lkb(rows,'name')), b=JSON.stringify(ekb(rows,r=>r.name));
  if (a!==b){ fails.keyBy++; samples.keyBy=samples.keyBy||[a,b]; }
}
const PRINT = []; for (let c=0x20;c<=0x7e;c++) PRINT.push(String.fromCharCode(c));
for (let i=0;i<200000;i++){
  let len=rnd(201), s=''; for(let j=0;j<len;j++) s+=pick(PRINT);
  if (lt(s,{length:24})!==etr(s,{length:24})) { fails.trunc++; samples.trunc=samples.trunc||[s,lt(s,{length:24}),etr(s,{length:24})]; }
}
console.log(JSON.stringify(fails), JSON.stringify(samples));
// the grading example inputs
console.log(JSON.stringify([lk("max44_id"), ek("max44_id"), lk(""), ek("")]));
EOF
node "$S/fuzz.cjs"

